/* ═══════════════════════════════════════════════════════
   TIPOS
═══════════════════════════════════════════════════════ */
export type Category = { id: string; name: string; emoji: string };

/**
 * Porte do produto — determina o modal de entrega possível.
 * P  = Pequeno   (≤ 2 kg, cabe em sacola/envelope)
 * M  = Médio     (2–15 kg, cabe no banco traseiro/porta-malas)
 * G  = Grande    (15–50 kg, precisa de carro grande ou van)
 * GG = Muito Grande (> 50 kg ou dimensão > 100 cm — caminhonete/caminhão)
 */
export type PorteProduto = "P" | "M" | "G" | "GG";

/**
 * Como o produto pode ser entregue:
 * motoboy   → moto ou carro parceiro (P com embalagem)
 * carro     → apenas carro parceiro (M com embalagem)
 * loja      → entrega especializada da própria loja (G/GG)
 * retirada  → apenas retirada no local (produto grande ou vendedor sem veículo)
 * combinado → acordar com o vendedor (itens de segunda mão)
 * servico   → o cliente leva o item ao prestador (assistência técnica)
 */
export type TipoEntrega = "motoboy" | "carro" | "loja" | "retirada" | "combinado" | "servico";

export type Logistica = {
  peso: number;                     // kg aproximado (0 = serviço)
  dims: [number, number, number];   // [altura, largura, comprimento] em cm
  porte: PorteProduto;
  temEmbalagem: boolean;
  entrega: TipoEntrega;
  prazo?: string;                   // ex: "Mesmo dia", "3-7 dias úteis"
  taxa?: number;                    // R$ (0 = frete grátis; undefined = a definir)
};

export type Store = {
  id: string;
  name: string;
  category: string;
  /** Cidade onde a loja está localizada — usada para regionalização */
  city: string;
  rating: number;
  reviews: number;
  distance: string;
  deliveryTime: string;
  image: string;
  description: string;
  freeShippingFrom?: number;
  sellerType: "cnpj" | "empreendedor" | "comum";
  verificationStatus: "nao_verificado" | "pendente" | "verificado" | "rejeitado";
  verificationType?: "cnpj" | "manual";
  cnpj?: string;
  address?: string;
  /** true = comércio local/urbano de bairro; omitido/false = grande rede nacional */
  isLocal?: boolean;
  /** URL do logotipo oficial (preferencialmente PNG com transparência) */
  logo?: string;
  /** Cor principal da marca em hex — usada no fallback quando o logo não carrega */
  brandColor?: string;
};

export type IndividualSeller = {
  id: string;
  name: string;
  avatar: string;
  city: string;
  memberSince: string;
  responseTime: string;
  accountInfo: string;
  rating: number;
  reviews: number;
  verificationStatus: "nao_verificado" | "pendente" | "verificado" | "rejeitado";
};

export type Product = {
  id: string;
  storeId?: string;
  sellerId?: string;
  name: string;
  price: number;
  originalPrice?: number;
  description: string;
  category: string;
  image: string;
  popular?: boolean;
  onSale?: boolean;
  logistica?: Logistica;
};

export type OrderStatus = "confirmado" | "preparando" | "saiu" | "entregue";

export type Order = {
  id: string;
  storeId: string;
  storeName: string;
  items: { productId: string; name: string; quantity: number; price: number }[];
  total: number;
  status: OrderStatus;
  customer: string;
  address: string;
  createdAt: string;
};

